cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should successfully search for a product', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('#search-query').type('drill');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('include', 'drill');
  });

  it('should not change URL on empty search', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('[data-test="search-submit"]').click();
    cy.url().should('eq', 'https://practicesoftwaretesting.com/');
    cy.get('#search-query').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Tool Shop Product Catalogue', () => {
  test('should successfully search for a product', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.fill('#search-query', 'drill');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL(/drill/);
  });

  test('should not change URL on empty search', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.click('[data-test="search-submit"]');
    await expect(page).toHaveURL('https://practicesoftwaretesting.com/');
    await expect(page.locator('#search-query')).toBeVisible();
  });
});
